RSpec.describe Timekeeping::EntryReader do
  it "drops entries of another company and entries naming another company's project when Timekeeping owns the data" do
    company_a = create(:company)
    company_b = create(:company)
    user = create(:user)
    create(:employment, company: company_a, user:)
    create(:employment, company: company_b, user:)
    project_a = create(:project, client: create(:client, company: company_a))
    project_b = create(:project, client: create(:client, company: company_b))
    ownership = TimekeepingOwnership.current
    ownership.update!(owner: "timekeeping", generation: 2)

    listed = lambda do |id, company_id, project_id|
      { "id" => id, "company_id" => company_id, "version" => 1, "project_id" => project_id, "user_id" => user.id,
        "work_date" => "2026-03-02", "duration" => 60.0, "note" => "entry #{id}", "bill_status" => "unbilled",
        "review_status" => "not_required", "source" => "manual", "source_metadata" => {}, "agent_id" => nil,
        "proof_url" => nil, "proof_metadata" => {}, "locked" => false }
    end
    answer = [listed.call(91_001, company_a.id, project_a.id),
              listed.call(91_002, company_b.id, project_b.id),
              listed.call(91_003, company_a.id, project_b.id)]
    timekeeping_client = Class.new do
      define_method(:list_entries) { |company_id:, user_id:, from:, to:, acting_user_id:| answer }
    end.new

    entries = described_class.list(company_id: company_a.id, user_id: user.id, from: Date.new(2026, 3, 1),
                                   to: Date.new(2026, 3, 31), ownership:, timekeeping_client:)

    expect(entries.map(&:id)).to eq([91_001])
    expect(entries.map { |entry| entry.snippet[:project] }).not_to include(project_b.name)
  end
end

